mapper.select:
SELECT 
FROM customer_address
WHERE id = #{id} AND customer_id = #{customerId}

mapper.update:
UPDATE customer_address
SET address = #{address}, consignee = #{consignee}, mobile = #{mobile}, be_default = #{beDefault}
WHERE id = #{id} AND customer_id = #{customerId}

mapper.select:
SELECT 
FROM customer_address
WHERE customer_id = #{customerId}
ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}
